from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The patterned field is a diagonal cycle: one palette step per move
    # right or down. Fit its period and phase-to-color mapping from visible cells.
    samples = [(r, c, grid[r][c])
               for r in range(3, h) for c in range(3, w)
               if grid[r][c] != 0]
    candidates = []
    for period in range(2, min(15, h + w)):
        phases = defaultdict(Counter)
        for r, c, color in samples:
            phases[(r + c) % period][color] += 1
        mapping = {phase: counts.most_common(1)[0][0]
                   for phase, counts in phases.items()}
        score = sum(mapping[(r + c) % period] == color
                    for r, c, color in samples)
        candidates.append((score, period, mapping))

    if candidates:
        max_score = max(x[0] for x in candidates)
        # Prefer the simplest cycle if its fit is within two exceptional
        # cells of the best fit (the visible corner contains a few irregulars).
        score, period, mapping = min(
            (x for x in candidates if x[0] >= max_score - 2),
            key=lambda x: x[1])
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 0:
                    continue
                if r < 2 or c < 2:
                    out[r][c] = 1
                elif r == 2 or c == 2:
                    out[r][c] = 4
                else:
                    out[r][c] = mapping[(r + c) % period]
    return out
